import { currentRoute, navigate, subscribeRoute } from './router.js';
import { openDatabase, getLocal, putLocal } from '../database/indexeddb.js';
import { firebaseConfigured, auth, db } from '../services/firebase.js';
import { onAuthStateChanged, createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut } from 'firebase/auth';
import { collection, addDoc, getDocs, query, where, orderBy, serverTimestamp, doc, updateDoc, setDoc } from 'firebase/firestore';

const fallback = [
 {id:'classic-burger',name:'Classic Burger',price:450,category:'Burgers',image:'classic-burger.png',description:'A delicious classic burger with fresh lettuce, tomatoes and special sauce.'},
 {id:'cheese-burger',name:'Cheese Burger',price:550,category:'Burgers',image:'cheese-burger.png',description:'Juicy grilled burger layered with melted cheese.'},
 {id:'chicken-burger',name:'Chicken Burger',price:500,category:'Burgers',image:'chicken-burger.png',description:'Crispy chicken, fresh vegetables and house sauce.'},
 {id:'beef-burger',name:'Beef Burger',price:600,category:'Burgers',image:'beef-burger.png',description:'Premium beef patty with fresh toppings.'},
 {id:'chicken-pizza',name:'Chicken Pizza',price:700,category:'Pizzas',image:'pizza.png',description:'Oven-baked pizza topped with chicken and cheese.'},
 {id:'fries',name:'French Fries',price:180,category:'Sides',image:'fries.png',description:'Golden crispy potato fries.'},
 {id:'iced-tea',name:'Iced Tea',price:160,category:'Drinks',image:'drinks.png',description:'Refreshing chilled drink.'}
];
const state={menu:fallback,cart:[],user:null,orders:[],category:'All',search:'',selected:'classic-burger',quantity:1,extraCheese:false,delivery:'Pickup',payment:'Cash on Delivery',filter:'All',adminTab:'Items'};
const money=n=>'Rs. '+Number(n||0).toLocaleString('en-PK');
const img=p=>'/QuickBite/images/'+p;
const el=(s)=>document.querySelector(s);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const product=id=>state.menu.find(p=>p.id===id)||state.menu[0];
const count=()=>state.cart.reduce((n,x)=>n+x.qty,0);
const subtotal=()=>state.cart.reduce((n,x)=>n+x.qty*x.price,0);
async function persistCart(){await putLocal('cart',{id:'active',items:state.cart});}
async function add(id=state.selected,qty=1){const p=product(id);const found=state.cart.find(x=>x.id===id);if(found)found.qty+=qty;else state.cart.push({id:p.id,name:p.name,price:p.price,image:p.image,qty});await persistCart();render();toast(p.name+' added to cart');}
function toast(message){let t=el('#toast');if(!t)return;t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200);}
function nav(){return '<nav class="bottom-nav"><a href="#/home">⌂<small>Home</small></a><a href="#/menu">♨<small>Menu</small></a><a href="#/orders">▤<small>Orders</small></a><a href="#/signin">♙<small>Account</small></a></nav>';}
function header(title,back=true){return '<header class="topbar">'+(back?'<button class="back" data-back>‹</button>':'<button class="hamb">☰</button>')+'<b>'+safe(title)+'</b><a href="#/cart" class="cart-link">🛒 <i>'+count()+'</i></a></header>';}
function brand(){return '<div class="brand"><span class="burger-mark">≋</span><strong>Quick<span>Bite</span></strong></div>';}
function card(p){return '<article class="food-card" data-product="'+p.id+'"><img src="'+img(p.image)+'" alt="'+safe(p.name)+'"><div><b>'+safe(p.name)+'</b><strong>'+money(p.price)+'</strong></div><button class="add" data-add="'+p.id+'" aria-label="Add '+safe(p.name)+'">+</button></article>';}
function products(){return state.menu.filter(p=>(state.category==='All'||p.category===state.category)&&p.name.toLowerCase().includes(state.search.toLowerCase()));}
function render(){
 const r=currentRoute(),app=el('#app');let html='';
 if(r==='welcome')html='<main class="auth-screen welcome"><div class="auth-brand">'+brand()+'<p>Good Food. Good Mood.</p></div><img class="welcome-food" src="'+img('welcome-burger.png')+'" alt="QuickBite signature burger"><section><h1>Delicious Food,<br>Delivered Fresh</h1><p>Experience restaurant-quality meals from the comfort of your home.</p><button class="primary" data-go="signin">Get Started →</button><button class="secondary" data-go="signin">Sign In</button><button class="guest" data-go="home">♟ Continue as Guest</button></section></main>';
 if(r==='signin'||r==='signup')html='<main class="auth-screen"><div class="auth-brand">'+brand()+'</div><section class="auth-form"><h1>'+(r==='signin'?'Welcome Back!':'Create Account')+'</h1><p>'+(r==='signin'?'Sign in to your account':'Join QuickBite today')+'</p><form id="auth-form">'+(r==='signup'?'<label>Full Name<input name="name" required placeholder="Full name"></label>':'')+'<label>Email Address<input name="email" type="email" autocomplete="email" required placeholder="Email Address"></label>'+(r==='signup'?'<label>Phone Number<input name="phone" type="tel" required placeholder="Phone Number"></label>':'')+'<label>Password<input name="password" type="password" minlength="6" required placeholder="Password"></label><button class="primary">'+(r==='signin'?'Sign In':'Create Account')+'</button></form><p class="switch-auth">'+(r==='signin'?'Don’t have an account?':'Already have an account?')+' <a href="#/'+(r==='signin'?'signup':'signin')+'">'+(r==='signin'?'Sign Up':'Sign In')+'</a></p><p class="or">— or continue as guest —</p><button class="secondary" data-go="home">Continue as Guest</button></section></main>';
 if(r==='home')html=header('QuickBite',false)+'<main class="page home-page"><section class="offer"><div><small>Special Offer</small><h1>50% OFF</h1><p>On All Burgers</p><button data-go="menu">Order Now →</button></div><img src="'+img('beef-burger.png')+'" alt="Burger offer"></section><label class="search">⌕ <input id="search" placeholder="Search delicious food..." value="'+safe(state.search)+'"></label><div class="categories">'+['Burgers','Pizzas','Drinks','Sides'].map((x,i)=>'<button data-category="'+x+'"><img src="'+img(['classic-burger.png','pizza.png','drinks.png','fries.png'][i])+'">'+x+'</button>').join('')+'</div><h2>Popular Items <a href="#/menu">See All →</a></h2><div class="food-list">'+state.menu.slice(0,4).map(card).join('')+'</div></main>'+nav();
 if(r==='menu')html=header('Our Menu')+'<main class="page"><div class="categories pills">'+['All','Burgers','Pizzas','Drinks','Sides'].map(x=>'<button class="'+(state.category===x?'selected':'')+'" data-category="'+x+'">'+x+'</button>').join('')+'</div><label class="search">⌕ <input id="search" placeholder="Search delicious food..." value="'+safe(state.search)+'"></label><div class="menu-grid">'+products().map(card).join('')+'</div></main>'+nav();
 if(r==='product'){const p=product(state.selected);html=header('')+'<main class="page product-page"><img class="product-hero" src="'+img(p.image)+'" alt="'+safe(p.name)+'"><h1>'+safe(p.name)+' <button class="heart">♡</button></h1><div class="rating">★★★★★ <small>4.8 (2.5k reviews)</small></div><p>'+safe(p.description)+'</p><h3>Customize Your Order</h3><div class="quantity"><span>Quantity</span><button data-qty="-1">−</button><b>'+state.quantity+'</b><button data-qty="1">+</button></div><label class="extra">Add Extra Cheese <span>+Rs. 50</span><input type="checkbox" id="cheese" '+(state.extraCheese?'checked':'')+'></label><div class="product-buy"><strong>'+money((p.price+(state.extraCheese?50:0))*state.quantity)+'</strong><button class="primary" data-product-add>Add to Cart →</button></div></main>';}
 if(r==='cart')html=header('Your Cart')+'<main class="page"><div class="cart-items">'+(state.cart.length?state.cart.map(x=>'<article class="cart-row"><img src="'+img(x.image)+'"><div><b>'+safe(x.name)+'</b><strong>'+money(x.price)+'</strong><div class="stepper"><button data-line="'+x.id+'" data-delta="-1">−</button>'+x.qty+'<button data-line="'+x.id+'" data-delta="1">+</button></div></div><button class="remove" data-remove="'+x.id+'">×</button></article>').join(''):'<div class="empty">Your cart is empty.<a href="#/menu">Explore menu</a></div>')+'</div><div class="bill"><p>Subtotal <b>'+money(subtotal())+'</b></p><p>Delivery Fee <b>'+money(state.delivery==='Delivery'?50:0)+'</b></p><h3>Total <b>'+money(subtotal()+(state.delivery==='Delivery'?50:0))+'</b></h3><button class="primary" data-go="checkout" '+(!state.cart.length?'disabled':'')+'>Proceed to Checkout →</button></div></main>'+nav();
 if(r==='checkout')html=header('Checkout')+'<main class="page"><h3>Delivery Method</h3><div class="choice-row"><button data-delivery="Pickup" class="'+(state.delivery==='Pickup'?'selected':'')+'">✚ Pickup <small>15-20 min</small></button><button data-delivery="Delivery" class="'+(state.delivery==='Delivery'?'selected':'')+'">♧ Delivery <small>30-45 min</small></button></div><h3>Payment Method</h3>'+['Cash on Delivery','JazzCash / Easypaisa','Card Payment'].map(x=>'<button class="option '+(state.payment===x?'selected':'')+'" data-payment="'+x+'">◉ '+x+'</button>').join('')+'<h3>Delivery Address</h3><textarea id="address" placeholder="Enter delivery address (required for delivery)"></textarea><h3>Order Notes (Optional)</h3><textarea id="notes" placeholder="Add special instructions..."></textarea><div class="bill"><h3>Total <b>'+money(subtotal()+(state.delivery==='Delivery'?50:0))+'</b></h3><button class="primary" id="place-order">Place Order →</button></div></main>';
 if(r==='tracking'){const o=state.orders[0];html=header('Order Tracking')+'<main class="page"><h2>'+(o?'Order #'+o.id.slice(-5):'Your order journey')+'</h2><div class="timeline">'+['Order Placed','Preparing Your Food','Out for Delivery','Delivered'].map((x,i)=>'<div class="time-step '+(i<=(o?['pending','preparing','out-for-delivery','delivered'].indexOf(o.status)+1:0)?'done':'')+'"><b>'+x+'</b><small>'+(i===0?'Order received':i===1?'Kitchen is preparing your meal':i===2?'Your order is on its way':'Enjoy your meal')+'</small></div>').join('')+'</div><div class="arrival">🛵 <span>Estimated Arrival<br><b>30–45 min</b></span></div></main>';}
 if(r==='orders')html=header('My Orders')+'<main class="page"><div class="categories pills">'+['All','Completed','Cancelled'].map(x=>'<button data-filter="'+x+'" class="'+(state.filter===x?'selected':'')+'">'+x+'</button>').join('')+'</div>'+(state.orders.length?state.orders.filter(o=>state.filter==='All'||o.status===state.filter.toLowerCase()).map(o=>'<article class="order-row"><img src="'+img(o.items[0]?.image||'classic-burger.png')+'"><div><b>#QK-'+o.id.slice(-4)+'</b><strong>'+money(o.total)+'</strong><small>'+safe(o.status)+' · '+new Date(o.createdAt).toLocaleDateString()+'</small></div><a href="#/tracking">Track →</a></article>').join(''):'<div class="empty">Your orders will appear here after placing an order.</div>')+'</main>'+nav();
 if(r==='admin')html='<aside class="admin-side">'+brand()+'<a href="#/admin">⌂ Dashboard</a><a href="#/manage-menu">▤ Manage Menu</a><a href="#/orders">▣ Orders</a></aside><main class="admin-main"><header class="admin-head"><h1>♛ Admin Dashboard</h1><span>● Admin</span></header><div class="stats"><article><small>Total Orders</small><b>'+state.orders.length+'</b></article><article><small>Total Sales</small><b>'+money(state.orders.reduce((n,o)=>n+o.total,0))+'</b></article></div><h2>Recent Orders</h2>'+state.orders.map(o=>'<article class="admin-order">#QK-'+o.id.slice(-4)+' · '+money(o.total)+' <select data-status="'+o.id+'">'+['pending','preparing','out-for-delivery','delivered','cancelled'].map(s=>'<option '+(o.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></article>').join('')+'</main>';
 if(r==='manage-menu')html='<aside class="admin-side">'+brand()+'<a href="#/admin">⌂ Dashboard</a><a class="active" href="#/manage-menu">▤ Manage Menu</a></aside><main class="admin-main"><header class="admin-head"><h1>Manage Menu</h1></header><div class="categories pills"><button class="selected">Items</button><button>Categories</button></div><form id="new-item" class="new-item"><input name="name" required placeholder="Item name"><input name="price" type="number" min="1" required placeholder="Price (Rs.)"><select name="category"><option>Burgers</option><option>Pizzas</option><option>Drinks</option><option>Sides</option></select><button class="primary">＋ Add Item</button></form>'+state.menu.map(p=>'<article class="manage-row"><img src="'+img(p.image)+'"><span>'+safe(p.name)+'<small>'+money(p.price)+'</small></span><label class="switch"><input type="checkbox" checked data-available="'+p.id+'"><i></i></label></article>').join('')+'</main>';
 app.innerHTML='<div class="qb-app">'+html+'</div><div id="toast" role="status" class="toast"></div>';
 bind();
}
function bind(){
 el('[data-back]')?.addEventListener('click',()=>history.back());
 document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));
 document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>add(b.dataset.add)));
 document.querySelectorAll('[data-product]').forEach(b=>b.addEventListener('click',e=>{if(e.target.closest('button'))return;state.selected=b.dataset.product;state.quantity=1;state.extraCheese=false;navigate('product');}));
 document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{state.category=b.dataset.category;render();}));
 el('#search')?.addEventListener('input',e=>{state.search=e.target.value;const pos=e.target.selectionStart;render();const input=el('#search');input.focus();input.setSelectionRange(pos,pos);});
 document.querySelectorAll('[data-qty]').forEach(b=>b.addEventListener('click',()=>{state.quantity=Math.max(1,state.quantity+Number(b.dataset.qty));render();}));
 el('#cheese')?.addEventListener('change',e=>{state.extraCheese=e.target.checked;render();});
 el('[data-product-add]')?.addEventListener('click',()=>add(state.selected,state.quantity));
 document.querySelectorAll('[data-line]').forEach(b=>b.addEventListener('click',async()=>{const x=state.cart.find(x=>x.id===b.dataset.line);x.qty+=Number(b.dataset.delta);if(x.qty<=0)state.cart=state.cart.filter(y=>y!==x);await persistCart();render();}));
 document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',async()=>{state.cart=state.cart.filter(x=>x.id!==b.dataset.remove);await persistCart();render();}));
 document.querySelectorAll('[data-delivery]').forEach(b=>b.addEventListener('click',()=>{state.delivery=b.dataset.delivery;render();}));
 document.querySelectorAll('[data-payment]').forEach(b=>b.addEventListener('click',()=>{state.payment=b.dataset.payment;render();}));
 el('#place-order')?.addEventListener('click',placeOrder);
 el('#auth-form')?.addEventListener('submit',authenticate);
 document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;render();}));
 el('#new-item')?.addEventListener('submit',addMenuItem);
 document.querySelectorAll('[data-status]').forEach(s=>s.addEventListener('change',()=>changeStatus(s.dataset.status,s.value)));
}
async function authenticate(e){e.preventDefault();const f=new FormData(e.target),email=f.get('email'),password=f.get('password');if(!firebaseConfigured){toast('Firebase is not configured yet.');return;}try{if(currentRoute()==='signup'){const cred=await createUserWithEmailAndPassword(auth,email,password);await setDoc(doc(db,'users',cred.user.uid),{uid:cred.user.uid,name:f.get('name'),phone:f.get('phone')||'',createdAt:serverTimestamp()});}else await signInWithEmailAndPassword(auth,email,password);navigate('home');}catch(err){toast(err.message);}}
async function placeOrder(){if(!state.cart.length)return;const address=el('#address')?.value.trim()||'';if(state.delivery==='Delivery'&&!address){toast('Please enter your delivery address.');return;}const total=subtotal()+(state.delivery==='Delivery'?50:0);const order={customerId:state.user?.uid||'guest',items:state.cart.map(x=>({...x})),total,status:'pending',delivery:state.delivery,payment:state.payment,address,notes:el('#notes')?.value||'',createdAt:new Date().toISOString()};try{if(firebaseConfigured&&state.user){const ref=await addDoc(collection(db,'orders'),{...order,createdAt:serverTimestamp()});order.id=ref.id;}else{order.id=crypto.randomUUID();const old=await getLocal('pending-orders','orders');await putLocal('pending-orders',{id:'orders',items:[...(old?.items||[]),order]});}state.orders.unshift(order);state.cart=[];await persistCart();navigate('tracking');}catch(err){toast('Order could not be placed: '+err.message);}}
async function addMenuItem(e){e.preventDefault();const f=new FormData(e.target),item={id:crypto.randomUUID(),name:f.get('name'),price:Number(f.get('price')),category:f.get('category'),image:'classic-burger.png',description:''};if(firebaseConfigured){try{await addDoc(collection(db,'menu'),item);}catch(err){toast(err.message);return;}}state.menu.push(item);render();toast('Menu item added');}
async function changeStatus(id,status){const o=state.orders.find(x=>x.id===id);if(o)o.status=status;if(firebaseConfigured){try{await updateDoc(doc(db,'orders',id),{status,updatedAt:serverTimestamp()});}catch(err){toast(err.message);}}render();}
async function loadData(){try{const cached=await getLocal('menu-cache','menu');if(cached?.items?.length)state.menu=cached.items;const cart=await getLocal('cart','active');if(cart?.items)state.cart=cart.items;const orders=await getLocal('pending-orders','orders');if(orders?.items)state.orders=orders.items;}catch(e){console.warn(e);}if(firebaseConfigured){try{const snap=await getDocs(query(collection(db,'menu'),orderBy('name')));if(!snap.empty){state.menu=snap.docs.map(d=>({id:d.id,...d.data()}));await putLocal('menu-cache',{id:'menu',items:state.menu});}}catch(e){console.warn('Menu sync unavailable',e);}}}
export async function startApp(){try{await openDatabase();}catch(e){console.error(e);}await loadData();if(auth)onAuthStateChanged(auth,async user=>{state.user=user;if(user&&db){try{const snap=await getDocs(query(collection(db,'orders'),where('customerId','==',user.uid)));state.orders=snap.docs.map(d=>({id:d.id,...d.data(),createdAt:d.data().createdAt?.toDate?.()?.toISOString?.()||new Date().toISOString()})).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));if(currentRoute()==='orders'||currentRoute()==='tracking')render();}catch(e){console.warn('Order history unavailable',e);}}});render();subscribeRoute(render);}
